/* Every actual program is selectable in setup, not only the eight exploratory interest themes. */
function catalogDirectionOptions(selected='',query='',school='',programId=''){const groups=new Map(),q=query.toLowerCase();for(const p of ProgramCatalog.programs){if(school&&p.institution!==school)continue;if(q&&![p.title,p.parentMajor,p.credential,p.institution].join(' ').toLowerCase().includes(q))continue;if(!groups.has(p.institution))groups.set(p.institution,[]);groups.get(p.institution).push(p)}const current=selected&&!programId?`<optgroup label="Current interest — choose an exact program below"><option value="${esc(selected)}" selected>${esc(selected)} (current broad direction)</option></optgroup>`:'';return current+[...groups].map(([name,rows])=>`<optgroup label="${esc(name)}">${rows.map(p=>`<option value="catalog:${esc(p.id)}" ${p.id===programId?'selected':''}>${esc(p.title)}${p.credential?' · '+esc(p.credential):''}</option>`).join('')}</optgroup>`).join('')+`<optgroup label="Broad interests — choose an exact program above when ready">${E.majors.filter(m=>programId||m.name!==selected).map(m=>`<option value="${esc(m.name)}" ${!programId&&m.name===selected?'selected':''}>${esc(m.name)} (broad direction)</option>`).join('')}</optgroup>`}
function catalogDirectionControl(id,selected='',programId=''){programId||=(state.degreeGoals||[]).find(g=>g.role==='primary'&&g.name===selected)?.programId||'';return `<label for="${id}-search">Search every loaded major or program</label><input id="${id}-search" type="search" data-direction-search="${id}" placeholder="Informatics, aerospace, business…" maxlength="150"><label for="${id}-school">Filter by college</label><select id="${id}-school" data-direction-school="${id}"><option value="">All listed colleges</option>${ProgramCatalog.institutions.map(s=>`<option>${esc(s.name)}</option>`).join('')}</select><select id="${id}" name="major" data-catalog-direction data-saved-program="${esc(programId)}"><option value="">I’m not sure yet</option>${catalogDirectionOptions(selected,'','',programId)}</select><p class="quiet-note" data-direction-count="${id}">${ProgramCatalog.programs.length} catalog entries available, including degrees, options and certificates. Exact campus and credential are saved with your choice.</p>`}
function resolveCatalogDirection(value,target=''){if(!String(value).startsWith('catalog:'))return{major:value,target,primaryProgramId:'',primaryProgram:''};const p=ProgramCatalog.programs.find(p=>p.id===value.slice(8));if(!p)throw Error('This catalog choice is unavailable. Choose another program.');const name={'UW Seattle':'University of Washington Seattle','UW Bothell':'University of Washington Bothell','UW Tacoma':'University of Washington Tacoma'}[p.institution]||p.institution;return{major:p.title,target:name,primaryProgram:p.title,primaryProgramId:p.id,calendar:ProductCore.institutions.find(c=>c.name===name)?.calendar||'Quarter'}}
function attachCatalogGoal(profile){if(!profile.primaryProgramId)return true;const p=ProgramCatalog.programs.find(p=>p.id===profile.primaryProgramId);if(!p)return false;state.degreeGoals||=[];if(state.degreeGoals.length>=6&&!state.degreeGoals.some(g=>g.role==='primary')){toast('Make room in your six saved goals before adding a primary program.');return false}const primary=state.degreeGoals.find(g=>g.role==='primary');if(primary?.programId===p.id)return true;const duplicate=state.degreeGoals.find(g=>g.programId===p.id&&g.role==='backup');if(duplicate){toast('This program is your backup. Change its role in the connected degree plan first.');return false}if(primary?.requirements?.length){if(state.degreeGoals.length>=6){toast('Your existing primary checklist is preserved. Make room in your six goals before choosing a new primary.');return false}primary.role='concurrent'}const next={id:primary&&!primary.requirements?.length?primary.id:degreeIds(),name:p.title,institution:p.institution,kind:p.credential||p.kind||'Program goal',role:'primary',source:p.url,programId:p.id,credential:p.credential||'',sharing:'review',advisorConfirmed:false,requirements:[]};if(primary&&!primary.requirements?.length)state.degreeGoals[state.degreeGoals.indexOf(primary)]=next;else state.degreeGoals.push(next);return true}
function bindCatalogDirections(){document.querySelectorAll('[data-compare-search]').forEach(input=>input.oninput=()=>{const select=document.querySelector('#compare'+input.dataset.compareSearch),old=select.value;select.innerHTML=catalogDirectionOptions(old.startsWith('catalog:')?'':old,input.value,'',old.startsWith('catalog:')?old.slice(8):'');if([...select.options].some(o=>o.value===old))select.value=old;});document.querySelectorAll('[data-catalog-direction]').forEach(select=>{const search=document.querySelector('[data-direction-search="'+select.id+'"]'),school=document.querySelector('[data-direction-school="'+select.id+'"]');const update=()=>{const old=select.value,legacy=old.startsWith('catalog:')?'':old,id=old.startsWith('catalog:')?old.slice(8):'';select.innerHTML='<option value="">I’m not sure yet</option>'+catalogDirectionOptions(legacy,search?.value||'',school?.value||'',id);if([...select.options].some(o=>o.value===old))select.value=old;const count=[...select.options].filter(o=>o.value.startsWith('catalog:')).length;document.querySelector('[data-direction-count="'+select.id+'"]')?.replaceChildren(document.createTextNode(count+' matching catalog programs. Your chosen campus and credential are saved.'))};if(search)search.oninput=update;if(school)school.onchange=update;select.addEventListener('change',()=>{if(!select.value.startsWith('catalog:'))return;const p=resolveCatalogDirection(select.value),form=select.form,target=form?.elements.namedItem('target'),calendar=form?.elements.namedItem('calendar');if(target){if(![...target.options].some(o=>o.value===p.target))target.add(new Option(p.target,p.target));target.value=p.target}if(calendar)calendar.value=p.calendar})})}
function installCatalogDirections(){const prior=bind;bind=()=>{prior();bindCatalogDirections();document.querySelectorAll('[data-replace-pathway]').forEach(el=>{const broadChange=el.onchange;el.onchange=()=>{if(!el.value.startsWith('catalog:'))return broadChange?.();const choice=resolveCatalogDirection(el.value,state.profile?.target);if(!attachCatalogGoal(choice))return;state.profile={...state.profile,...choice};save();location.hash='profile';render()}})}}
